const MANIFEST = {
  "type": "Layout.Accordion",
  "description": "Expandable accordion with smooth height animations and rotating icons",
  "editorElement": {
    "selector": ".accordion",
    "displayName": "Accordion",
    "archetype": "container",
    "data": {
      "items": {
        "dataType": "text",
        "displayName": "Accordion Items",
        "defaultValue": "What makes this different?|Our approach combines cutting-edge technology with human-centered design principles to create solutions that are both powerful and intuitive.,How does pricing work?|We offer flexible pricing tiers designed to scale with your needs. Start free and upgrade as your requirements grow.,Is there a free trial?|Yes! We offer a 14-day free trial with full access to all features. No credit card required to get started.,What support options are available?|We provide 24/7 email support for all plans, with priority phone support available for premium tiers.",
        "group": "Content",
        "description": "Format: Title|Content, separated by commas"
      },
      "allowMultiple": {
        "dataType": "booleanValue",
        "displayName": "Allow Multiple Open",
        "defaultValue": "false",
        "group": "Content"
      },
      "defaultOpen": {
        "dataType": "select",
        "displayName": "Default Open Item",
        "defaultValue": "none",
        "options": ["none", "0", "1", "2", "3"],
        "group": "Content"
      },
      "iconPosition": {
        "dataType": "select",
        "displayName": "Icon Position",
        "defaultValue": "right",
        "options": ["left", "right"],
        "group": "Layout"
      },
      "iconStyle": {
        "dataType": "select",
        "displayName": "Icon Style",
        "defaultValue": "chevron",
        "options": ["chevron", "plus", "arrow"],
        "group": "Layout"
      },
      "transitionDuration": {
        "dataType": "select",
        "displayName": "Transition Duration (ms)",
        "defaultValue": "300",
        "options": ["200", "300", "400", "500"],
        "group": "Animation"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Container Background",
        "defaultValue": "#FAFAF9",
        "group": "Colors"
      },
      "itemBackground": {
        "dataType": "color",
        "displayName": "Item Background",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "headerColor": {
        "dataType": "color",
        "displayName": "Header Text Color",
        "defaultValue": "#1C1917",
        "group": "Colors"
      },
      "contentColor": {
        "dataType": "color",
        "displayName": "Content Text Color",
        "defaultValue": "#78716C",
        "group": "Colors"
      },
      "iconColor": {
        "dataType": "color",
        "displayName": "Icon Color",
        "defaultValue": "#A8A29E",
        "group": "Colors"
      },
      "iconActiveColor": {
        "dataType": "color",
        "displayName": "Icon Active Color",
        "defaultValue": "#44403C",
        "group": "Colors"
      },
      "borderColor": {
        "dataType": "color",
        "displayName": "Border Color",
        "defaultValue": "#E7E5E4",
        "group": "Colors"
      },
      "hoverBackground": {
        "dataType": "color",
        "displayName": "Hover Background",
        "defaultValue": "#F5F5F4",
        "group": "Colors"
      },
      "headerFontSize": {
        "dataType": "number",
        "displayName": "Header Font Size (px)",
        "defaultValue": 16,
        "group": "Typography"
      },
      "contentFontSize": {
        "dataType": "number",
        "displayName": "Content Font Size (px)",
        "defaultValue": 15,
        "group": "Typography"
      },
      "headerFontWeight": {
        "dataType": "select",
        "displayName": "Header Font Weight",
        "defaultValue": "500",
        "options": ["400", "500"],
        "group": "Typography"
      },
      "containerPadding": {
        "dataType": "select",
        "displayName": "Container Padding",
        "defaultValue": "24",
        "options": ["16", "24", "32", "40"],
        "group": "Layout"
      },
      "itemGap": {
        "dataType": "select",
        "displayName": "Item Gap (px)",
        "defaultValue": "8",
        "options": ["0", "4", "8", "12"],
        "group": "Layout"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  var itemsRaw = config?.items || 'What makes this different?|Our approach combines cutting-edge technology with human-centered design principles.,How does pricing work?|We offer flexible pricing tiers designed to scale with your needs.,Is there a free trial?|Yes! We offer a 14-day free trial with full access to all features.,What support is available?|We provide 24/7 email support for all plans.';
  var allowMultiple = config?.allowMultiple === true;
  var defaultOpen = config?.defaultOpen || 'none';
  var iconPosition = config?.iconPosition || 'right';
  var iconStyle = config?.iconStyle || 'chevron';
  var transitionDuration = parseInt(config?.transitionDuration || '300');

  var backgroundColor = config?.backgroundColor || '#FAFAF9';
  var itemBackground = config?.itemBackground || '#FFFFFF';
  var headerColor = config?.headerColor || '#1C1917';
  var contentColor = config?.contentColor || '#78716C';
  var iconColor = config?.iconColor || '#A8A29E';
  var iconActiveColor = config?.iconActiveColor || '#44403C';
  var borderColor = config?.borderColor || '#E7E5E4';
  var hoverBackground = config?.hoverBackground || '#F5F5F4';

  var headerFontSize = parseInt(config?.headerFontSize || '16');
  var contentFontSize = parseInt(config?.contentFontSize || '15');
  var headerFontWeight = config?.headerFontWeight || '500';
  var containerPadding = parseInt(config?.containerPadding || '24');
  var itemGap = parseInt(config?.itemGap || '8');

  var items = React.useMemo(function() {
    return itemsRaw.split(',').map(function(item, index) {
      var parts = item.split('|').map(function(s) { return s.trim(); });
      return { id: index, title: parts[0] || 'Item ' + (index + 1), content: parts[1] || '' };
    });
  }, [itemsRaw]);

  var getInitialOpen = function() {
    if (defaultOpen === 'none') return [];
    var index = parseInt(defaultOpen);
    return index < items.length ? [index] : [];
  };

  var _openItems = React.useState(getInitialOpen());
  var openItems = _openItems[0];
  var setOpenItems = _openItems[1];

  var _hoveredItem = React.useState(null);
  var hoveredItem = _hoveredItem[0];
  var setHoveredItem = _hoveredItem[1];

  var toggleItem = function(id) {
    if (allowMultiple) {
      setOpenItems(function(prev) {
        return prev.indexOf(id) !== -1 
          ? prev.filter(function(i) { return i !== id; }) 
          : prev.concat([id]);
      });
    } else {
      setOpenItems(function(prev) {
        return prev.indexOf(id) !== -1 ? [] : [id];
      });
    }
  };

  var isOpen = function(id) {
    return openItems.indexOf(id) !== -1;
  };

  var renderIcon = function(open) {
    var iconProps = {
      width: 20,
      height: 20,
      viewBox: '0 0 20 20',
      fill: 'none',
      style: {
        transform: iconStyle === 'chevron' 
          ? (open ? 'rotate(180deg)' : 'rotate(0deg)')
          : iconStyle === 'arrow'
            ? (open ? 'rotate(90deg)' : 'rotate(0deg)')
            : 'none',
        transition: 'transform ' + transitionDuration + 'ms ease'
      }
    };

    if (iconStyle === 'chevron') {
      return React.createElement('svg', iconProps,
        React.createElement('path', {
          d: 'M5 7.5L10 12.5L15 7.5',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        })
      );
    }

    if (iconStyle === 'plus') {
      return React.createElement('svg', iconProps, [
        React.createElement('path', {
          key: 'v',
          d: 'M10 4V16',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          style: {
            opacity: open ? 0 : 1,
            transform: open ? 'rotate(90deg)' : 'rotate(0deg)',
            transformOrigin: 'center',
            transition: 'all ' + transitionDuration + 'ms ease'
          }
        }),
        React.createElement('path', {
          key: 'h',
          d: 'M4 10H16',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round'
        })
      ]);
    }

    if (iconStyle === 'arrow') {
      return React.createElement('svg', iconProps,
        React.createElement('path', {
          d: 'M7.5 5L12.5 10L7.5 15',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        })
      );
    }

    return null;
  };

  return React.createElement('div', {
    className: 'accordion',
    style: {
      backgroundColor: backgroundColor,
      padding: containerPadding + 'px',
      minHeight: '200px'
    }
  }, React.createElement('div', {
    style: {
      display: 'flex',
      flexDirection: 'column',
      gap: itemGap + 'px'
    }
  }, items.map(function(item) {
    var itemIsOpen = isOpen(item.id);
    var isHovered = hoveredItem === item.id;

    return React.createElement('div', {
      key: item.id,
      style: {
        backgroundColor: itemBackground,
        borderRadius: '8px',
        border: '1px solid ' + borderColor,
        overflow: 'hidden'
      }
    }, [
      React.createElement('button', {
        key: 'header',
        onClick: function() { toggleItem(item.id); },
        onMouseEnter: function() { setHoveredItem(item.id); },
        onMouseLeave: function() { setHoveredItem(null); },
        'aria-expanded': itemIsOpen,
        style: {
          width: '100%',
          padding: '16px 20px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          flexDirection: iconPosition === 'left' ? 'row-reverse' : 'row',
          gap: '12px',
          background: isHovered ? hoverBackground : 'transparent',
          border: 'none',
          cursor: 'pointer',
          textAlign: 'left',
          transition: 'background-color ' + transitionDuration + 'ms ease'
        }
      }, [
        React.createElement('span', {
          key: 'title',
          style: {
            fontSize: headerFontSize + 'px',
            fontWeight: headerFontWeight,
            color: headerColor,
            fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
            flex: 1
          }
        }, item.title),

        React.createElement('span', {
          key: 'icon',
          style: {
            color: itemIsOpen ? iconActiveColor : iconColor,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            flexShrink: 0,
            transition: 'color ' + transitionDuration + 'ms ease'
          }
        }, renderIcon(itemIsOpen))
      ]),

      React.createElement('div', {
        key: 'content',
        style: {
          maxHeight: itemIsOpen ? '500px' : '0',
          opacity: itemIsOpen ? 1 : 0,
          overflow: 'hidden',
          transition: 'all ' + transitionDuration + 'ms cubic-bezier(0.4, 0, 0.2, 1)'
        }
      }, React.createElement('div', {
        style: {
          padding: '0 20px 20px 20px',
          borderTop: '1px solid ' + borderColor
        }
      }, React.createElement('p', {
        style: {
          fontSize: contentFontSize + 'px',
          color: contentColor,
          margin: 0,
          paddingTop: '16px',
          lineHeight: 1.7,
          fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
        }
      }, item.content)))
    ]);
  })));
}

