        "displayName": "Border Color",
        "defaultValue": "#27272A",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const [expandedIndex, setExpandedIndex] = React.useState(0);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const sectionTitle = config?.sectionTitle || 'Our Expertise';
  const sectionSubtitle = config?.sectionSubtitle || 'Click to explore each service area';

  const services = [
    {
      title: config?.service1Title || 'Strategic Consulting',
      description: config?.service1Description || 'Transform your business with data-driven strategies.',
      number: config?.service1Number || '01'
    },
    {
      title: config?.service2Title || 'Digital Products',
      description: config?.service2Description || 'Build digital products that users love.',
      number: config?.service2Number || '02'
    },
    {
      title: config?.service3Title || 'Brand Identity',
      description: config?.service3Description || 'Create a memorable brand that resonates.',
      number: config?.service3Number || '03'
    },
    {
      title: config?.service4Title || 'Growth Marketing',
      description: config?.service4Description || 'Accelerate your growth with proven strategies.',
      number: config?.service4Number || '04'
    }
  ];

  const collapsedHeight = parseInt(config?.collapsedHeight || '80');
  const expandedHeight = parseInt(config?.expandedHeight || '240');
  const cardGap = parseInt(config?.cardGap || '8');
  const maxWidth = parseInt(config?.maxWidth || '700');

  const backgroundColor = config?.backgroundColor || '#0C0C0C';
  const cardBackgroundColor = config?.cardBackgroundColor || '#161616';
  const expandedCardBg = config?.expandedCardBg || '#1A1A1A';
  const titleColor = config?.titleColor || '#FFFFFF';
  const textColor = config?.textColor || '#A1A1AA';
  const numberColor = config?.numberColor || '#3F3F46';
  const accentColor = config?.accentColor || '#FFFFFF';
  const borderColor = config?.borderColor || '#27272A';

  const uniqueId = React.useMemo(() => {
    return typeof React.useId === 'function'
      ? React.useId().replace(/:/g, '')
      : `id-${Math.random().toString(36).substr(2, 9)}`;
  }, []);

  const handleCardClick = (index) => {
    setExpandedIndex(expandedIndex === index ? -1 : index);
  };

  const getCardStyle = (index) => {
    const isExpanded = expandedIndex === index;

    return {
      width: '100%',
      height: isExpanded ? expandedHeight + 'px' : collapsedHeight + 'px',
      backgroundColor: isExpanded ? expandedCardBg : cardBackgroundColor,
      borderRadius: '12px',
      border: `1px solid ${isExpanded ? accentColor + '30' : borderColor}`,
      padding: '0 28px',
      cursor: 'pointer',
      overflow: 'hidden',
      transition: prefersReducedMotion ? 'none' : 'all 500ms cubic-bezier(0.34, 1.56, 0.64, 1)',
      position: 'relative'
    };
  };

  return (
    <div
      className="accordion-stack-cards"
      style={{
        backgroundColor,
        padding: '80px 40px',
        minHeight: '700px'
      }}
    >
      {/* Section Header */}
      <div
        style={{
          maxWidth: maxWidth + 'px',
          margin: '0 auto 48px'
        }}
      >
        <h2
          style={{
            fontSize: '36px',
            fontWeight: '500',
            color: titleColor,
            margin: '0 0 12px 0',
            letterSpacing: '-0.02em'
          }}
        >
          {sectionTitle}
        </h2>
        <p
          style={{
            fontSize: '15px',
            color: textColor,
            margin: 0
          }}
        >
          {sectionSubtitle}
        </p>
      </div>

      {/* Accordion Cards */}
      <div
        style={{
          maxWidth: maxWidth + 'px',
          margin: '0 auto',
          display: 'flex',
          flexDirection: 'column',
          gap: cardGap + 'px'
        }}
      >
        {services.map((service, index) => {
          const isExpanded = expandedIndex === index;

          return (
            <div
              key={`${uniqueId}-accordion-${index}`}
              style={getCardStyle(index)}
              onClick={() => handleCardClick(index)}
              role="button"
              tabIndex={0}
              aria-expanded={isExpanded}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault();
                  handleCardClick(index);
                }
              }}
            >
              {/* Collapsed Header */}
              <div
                style={{
                  height: collapsedHeight + 'px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between'
                }}
              >
                <div
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '20px'
                  }}
                >
                  {/* Number */}
                  <span
                    style={{
                      fontSize: '14px',
                      fontWeight: '500',
                      color: isExpanded ? accentColor : numberColor,
                      fontFamily: 'monospace',
                      transition: prefersReducedMotion ? 'none' : 'color 300ms ease-out'
                    }}
                  >
                    {service.number}
                  </span>

                  {/* Title */}
                  <h3
                    style={{
                      fontSize: '18px',
                      fontWeight: '500',
                      color: titleColor,
                      margin: 0
                    }}
                  >
                    {service.title}
                  </h3>
                </div>

                {/* Expand Icon */}
                <div
                  style={{
                    width: '32px',
                    height: '32px',
                    borderRadius: '50%',
                    backgroundColor: isExpanded ? accentColor : borderColor,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out'
                  }}
                >
                  <span
                    style={{
                      color: isExpanded ? backgroundColor : textColor,
                      fontSize: '18px',
                      transform: `rotate(${isExpanded ? 45 : 0}deg)`,
                      transition: prefersReducedMotion ? 'none' : 'transform 300ms ease-out',
                      lineHeight: 1
                    }}
                  >
                    +
                  </span>
                </div>
              </div>

              {/* Expanded Content */}
              <div
                style={{
                  opacity: isExpanded ? 1 : 0,
                  transform: `translateY(${isExpanded ? 0 : -10}px)`,
                  transition: prefersReducedMotion ? 'none' : 'all 400ms ease-out',
                  paddingBottom: isExpanded ? '28px' : 0
                }}
              >
                <p
                  style={{
                    fontSize: '15px',
                    color: textColor,
                    margin: '0 0 24px 0',
                    lineHeight: '1.7',
                    paddingLeft: '54px'
                  }}
                >
                  {service.description}
                </p>

                {/* CTA Button */}
                <div
                  style={{
                    paddingLeft: '54px'
                  }}
                >
                  <button
                    style={{
                      padding: '10px 20px',
                      backgroundColor: 'transparent',
                      border: `1px solid ${borderColor}`,
                      borderRadius: '6px',
                      color: titleColor,
                      fontSize: '13px',
                      fontWeight: '500',
                      cursor: 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      gap: '8px',
                      transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out'
                    }}
                    onClick={(e) => e.stopPropagation()}
                    onMouseEnter={(e) => {
                      e.target.style.backgroundColor = accentColor;
                      e.target.style.color = backgroundColor;
                      e.target.style.borderColor = accentColor;
                    }}
                    onMouseLeave={(e) => {
                      e.target.style.backgroundColor = 'transparent';
                      e.target.style.color = titleColor;
                      e.target.style.borderColor = borderColor;
                    }}
                  >
                    Learn more
                    <span>→</span>
                  </button>
                </div>
              </div>

              {/* Progress Line */}
              <div
                style={{
                  position: 'absolute',
                  bottom: 0,
                  left: 0,
                  width: `${((index + 1) / services.length) * 100}%`,
                  height: '2px',
                  backgroundColor: accentColor,
                  opacity: isExpanded ? 0.3 : 0,
                  transition: prefersReducedMotion ? 'none' : 'opacity 300ms ease-out'
                }}
              />
            </div>
          );
        })}
      </div>

      {/* Footer Note */}
      <div
        style={{
          maxWidth: maxWidth + 'px',
          margin: '40px auto 0',
          textAlign: 'center'
        }}
      >
        <p
          style={{
            fontSize: '13px',
            color: numberColor,
            margin: 0
          }}
        >
          {expandedIndex >= 0 ? `Viewing: ${services[expandedIndex]?.title}` : 'Select a service to learn more'}
        </p>
      </div>
    </div>
  );
}

