                      stroke={iconColor}
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                </button>

                {/* Answer Content */}
                <div
                  ref={el => contentRefs.current[index] = el}
                  style={{
                    maxHeight: isOpen ? (contentRefs.current[index]?.scrollHeight + 'px') : '0px',
                    opacity: prefersReducedMotion ? (isOpen ? 1 : 0) : undefined,
                    overflow: 'hidden',
                    transition: prefersReducedMotion ? 'opacity 200ms ease-out' : 'max-height 400ms cubic-bezier(0.22, 1, 0.36, 1), opacity 200ms ease-out'
                  }}
                >
                  <div style={{
                    padding: '0 20px 20px 20px',
                    fontSize: `${answerSize}px`,
                    color: answerColor,
                    lineHeight: '1.7'
                  }}>
                    {item.answer}
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* No Results */}
        {filteredItems.length === 0 && (
          <div style={{
            textAlign: 'center',
            padding: '60px 20px',
            color: answerColor
          }}>
            <div style={{ fontSize: '48px', marginBottom: '16px' }}>🔍</div>
            <div style={{ fontSize: '18px', fontWeight: '500', marginBottom: '8px' }}>
              No questions found
            </div>
            <div style={{ fontSize: '14px' }}>
              Try adjusting your search term
            </div>
          </div>
        )}
      </div>

      <style>{`
        @keyframes itemAppear {
          from {
            opacity: 0;
            transform: translateY(10px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
      `}</style>
    </div>
  );
}

